// Splits already-HTML-escaped text into one <span class="reveal-word"> per
// word, each carrying its own staggered animation-delay, so a text block's
// CSS reveal (.scroll-reveal.in-view .reveal-word, see index.html) plays
// word-by-word instead of the whole paragraph fading in as one flat unit
// (owner: "live animation of words appearing as one scrolls down"). Splits
// on runs of whitespace and passes whitespace tokens through unwrapped --
// this preserves the surrounding <p>'s white-space:pre-line line breaks
// exactly as before, and keeps the (already-escaped) HTML entities intact
// since none of them contain whitespace internally. The per-word delay is
// capped at 40 words so a long paragraph's tail doesn't end up waiting
// several seconds to appear.
function revealWordsHtml(escapedText){
  let wordIndex = 0;
  return String(escapedText).split(/(\s+)/).map(tok => {
    if (!tok || /^\s+$/.test(tok)) return tok;
    const delay = Math.min(wordIndex, 40) * 30;
    wordIndex++;
    return `<span class="reveal-word" style="animation-delay:${delay}ms">${tok}</span>`;
  }).join('');
}
// About page: an admin-authored ordered list of text/image blocks (see
// /public/about-content), rendered as an article and revealed block-by-
// block as the member scrolls (owner: "whenever one scrolls down, images
// and words I placed show animation").
let _aboutScrollObserver = null;
window.openAboutSheet = async function(){
  const s = STATE.settings || {};
  openSheet('About Snow', `<div id="aboutArticle" class="reveal-in"><p style="color:var(--snow-muted);">Loading…</p></div>`);
  const r = await api('/public/about-content');
  const wrap = $('aboutArticle');
  if (!wrap) return; // sheet was closed again before this resolved
  const blocks = (r.status === 'success' && Array.isArray(r.blocks) && r.blocks.length) ? r.blocks
    : [{ type: 'text', text: s.aboutText || 'Snow lets you invest in a range of plans with daily cashback and a 3-level referral program.' }];
  wrap.innerHTML = blocks.map(b => b.type === 'image'
    ? `<div class="scroll-reveal about-image about-block"><img src="${esc(b.image)}" style="width:100%;display:block;border-radius:0;" alt=""></div>`
    : `<div class="scroll-reveal about-block"><p style="white-space:pre-line;line-height:1.7;color:var(--snow-ink);">${revealWordsHtml(esc(b.text))}</p></div>`
  ).join('');
  if (_aboutScrollObserver) _aboutScrollObserver.disconnect();
  _aboutScrollObserver = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) { e.target.classList.add('in-view'); _aboutScrollObserver.unobserve(e.target); }
    });
  }, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });
  wrap.querySelectorAll('.scroll-reveal').forEach(el => _aboutScrollObserver.observe(el));
};

// Owner: "make daily checkin to reset at 00:00 not 24hrs" -- reverts back to
// a calendar-midnight (EAT, UTC+3) daily reset instead of Round 87's rolling
// 24h cooldown. STATE.account.lastCheckinAt is still the real epoch-ms
// timestamp server.js already returns -- only the "when does the cooldown
// lift" math changes, from "+24h" to "the next EAT midnight after
// lastCheckinAt's own calendar day." The live "Available in HH:MM:SS"
// countdown (same startCheckinCountdown() ticking pattern
// startPlanCountdowns() already uses on My Products) is kept -- it now
// counts down to that real midnight instant instead of a moving +24h target.
function eatDayIndex(ts){ return Math.floor((ts + 3 * 3600000) / 86400000); }
function eatMidnightAfter(ts){ return (eatDayIndex(ts) + 1) * 86400000 - 3 * 3600000; }
window.openCheckinSheet = function(){
  const a = STATE.account || {};
  const bonus = Number(STATE.settings && STATE.settings.dailyCheckin) || 0;
  const streak = Number(a.checkinStreak) || 0;
  const now = Date.now();
  const lastAt = a.lastCheckinAt ? Number(a.lastCheckinAt) : 0;
  const onCooldown = !!lastAt && eatDayIndex(lastAt) === eatDayIndex(now);
  const nextAt = onCooldown ? eatMidnightAfter(now) : 0;
  openSheet('Daily Check-in', `<div class="reveal-in">
    <div class="app-card" style="padding:24px 20px;text-align:center;">
      <div style="font-size:12.5px;color:var(--snow-muted);text-transform:uppercase;letter-spacing:.5px;">Current streak</div>
      <div class="mono" style="font-size:36px;font-weight:800;margin-top:6px;color:var(--snow-green);">${streak}<span style="font-size:15px;font-weight:600;color:var(--snow-muted);"> day${streak===1?'':'s'}</span></div>
      <div style="font-size:13px;color:var(--snow-muted);margin-top:12px;line-height:1.5;">Check in once every day (resets at midnight) to keep your streak and earn ${fmtUGX(bonus)} each time.</div>
      <button class="primary-button" id="checkinBtn" data-checkin-next="${nextAt}" style="width:100%;padding:15px 0;font-size:15px;margin-top:20px;" ${onCooldown?'disabled':''} onclick="submitCheckin()">${onCooldown?'Available in <span class="countdown-val">--:--:--</span>':'Check In &middot; '+fmtUGX(bonus)}</button>
    </div>
  </div>`);
  if (onCooldown) startCheckinCountdown();
};
// Self-terminating, same idiom as startPlanCountdowns(): the tick just stops
// itself once #checkinBtn's countdown attribute is gone (sheet closed or
// re-rendered), no separate close-hook needed. Once the cooldown genuinely
// reaches zero, flips the button live to its claimable state -- no manual
// refresh/reopen needed to see the app catch up.
var _checkinCountdownTimer = null;
function startCheckinCountdown(){
  if (_checkinCountdownTimer) clearInterval(_checkinCountdownTimer);
  const tick = () => {
    // Subagent-audit-caught real bug: this only ever checked whether the
    // button node still exists in the DOM -- but closeSheet()/popstate never
    // clear #sheetBody's innerHTML (only toggle the overlay's .show class),
    // so the button stays findable by a document-wide querySelector long
    // after the Daily Check-in sheet is visually closed. Without the
    // _openSheetTitle check every other countdown timer in this file already
    // uses (see _manPayTimerInterval's own tick), this kept ticking on a
    // now-invisible, detached-from-view node for up to ~24h after the
    // member navigated away -- a real battery/CPU drain, not just a style
    // inconsistency.
    if (_openSheetTitle !== 'Daily Check-in') { clearInterval(_checkinCountdownTimer); _checkinCountdownTimer = null; return; }
    const btn = document.querySelector('[data-checkin-next]');
    if (!btn) { clearInterval(_checkinCountdownTimer); _checkinCountdownTimer = null; return; }
    const remaining = Number(btn.dataset.checkinNext) - Date.now();
    if (remaining <= 0) {
      clearInterval(_checkinCountdownTimer); _checkinCountdownTimer = null;
      btn.removeAttribute('data-checkin-next');
      btn.disabled = false;
      const bonus = Number(STATE.settings && STATE.settings.dailyCheckin) || 0;
      btn.innerHTML = 'Check In &middot; ' + fmtUGX(bonus);
      return;
    }
    const val = btn.querySelector('.countdown-val');
    if (val) {
      const h = Math.floor(remaining / 3600000);
      const m = Math.floor((remaining % 3600000) / 60000);
      const s = Math.floor((remaining % 60000) / 1000);
      const pad = n => String(n).padStart(2, '0');
      val.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
    }
  };
  tick();
  _checkinCountdownTimer = setInterval(tick, 1000);
}
window.submitCheckin = async function(){
  const btn = $('checkinBtn');
  if (!btn || btn.disabled) return;
  const label = btn.textContent;
  btn.disabled = true; btn.textContent = 'Checking in…';
  const r = await post('/checkin', {});
  if (r.status !== 'success') {
    btn.disabled = false; btn.textContent = label;
    return toast(r.message || 'Could not check in', true);
  }
  toast(`Check-in successful. ${fmtUGX(r.bonus)} added to your wallet`);
  const acc = await api('/account');
  if (acc.status === 'success') STATE.account = acc.account;
  // Same stale-Records fix Round 72 applied to deposit/withdraw --
  // /checkin already wrote a real ledger row server-side by this point;
  // without this, Records' Income tab could sit stale for a reload or two
  // (owner: "some records are created or reflect after reloading").
  await refreshTransactionsCache();
  closeSheet({ fromAction: true });
  if (STATE.page === 'home') renderHome();
};

// Treasure chest on Home -- opens a centered popup (not a bottom sheet) to
